{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function ser(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  switch (node.t) {
    case 'table': {
      const ks = sortedKeys(node)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + ser(node.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!node.items.length) return '[]'
      return '[\n' + node.items.map((i) => pad + ser(i, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'integer': return node.v.toString()
    case 'float': return JSON.stringify(node.v)
    case 'string': return JSON.stringify(node.v)
    default: return node.v ? 'true' : 'false'
  }
}

export const toJson = (root) => ser(root, 0) + '\n'

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) visit(node.map.get(k), path === null ? k : path + '.' + k)
    } else {
      node.items.forEach((it, i) => visit(it, path + '[' + i + ']'))
    }
  }
  const visit = (node, path) => {
    lines.push(path + ' ' + node.t)
    if (node.t === 'table' || node.t === 'array') walk(node, path)
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

