{"file_path":"src/parser.js","content":"export class ParseError extends Error {}

const fail = (m) => { throw new ParseError(m) }
const newTable = () => ({ t: 'table', map: new Map(), hdr: false })
const isWs = (c) => c === ' ' || c === '\t'
const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(?:_\d+)*$/
const FLOAT = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*(?:[eE][+-]?\d+(?:_\d+)*)?|[eE][+-]?\d+(?:_\d+)*)$/

const join = (p) => p.join('.')

// Walk the intermediate segments, creating tables; returns the table holding the last segment.
function walk(table, base, segs) {
  let cur = table
  for (let i = 0; i < segs.length - 1; i++) {
    const k = segs[i]
    const child = cur.map.get(k)
    if (child === undefined) {
      const t = newTable()
      cur.map.set(k, t)
      cur = t
    } else if (child.t === 'table') {
      cur = child
    } else if (child.t === 'array' && child.tables) {
      cur = child.items[child.items.length - 1]
    } else {
      fail(`${join([...base, ...segs.slice(0, i + 1)])} is not a table`)
    }
  }
  return cur
}

class Line {
  constructor(s) { this.s = s; this.p = 0 }
  ws() { while (isWs(this.s[this.p])) this.p++ }
  // at end of line or at a comment, after whitespace
  atEnd() {
    this.ws()
    const c = this.s[this.p]
    return c === undefined || c === '#' || c === ';'
  }
  peek() { return this.s[this.p] }

  quoted() {
    const s = this.s
    const q = s[this.p++]
    let out = ''
    if (q === "'") {
      const e = s.indexOf("'", this.p)
      if (e < 0) fail('unterminated string')
      out = s.slice(this.p, e)
      this.p = e + 1
      return out
    }
    for (;;) {
      const c = s[this.p]
      if (c === undefined) fail('unterminated string')
      this.p++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const e = s[this.p]
      if (e === undefined) fail('unterminated string')
      this.p++
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(simple, e)) out += simple[e]
      else if (e === 'u') {
        const h = s.slice(this.p, this.p + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.p += 4
      } else {
        const cp = String.fromCodePoint(s.codePointAt(this.p - 1))
        fail(`invalid escape \\${cp}`)
      }
    }
  }

  name() {
    this.ws()
    const c = this.peek()
    if (c === '"' || c === "'") return this.quoted()
    const st = this.p
    while (this.p < this.s.length && BARE.test(this.s[this.p])) this.p++
    if (this.p === st) fail('expected a name')
    return this.s.slice(st, this.p)
  }

  dotted() {
    const segs = [this.name()]
    for (;;) {
      this.ws()
      if (this.peek() !== '.') return segs
      this.p++
      segs.push(this.name())
    }
  }

  value(base) {
    this.ws()
    const c = this.peek()
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.p
    while (this.p < this.s.length && !isWs(this.s[this.p]) && !',]}'.includes(this.s[this.p])) this.p++
    const w = this.s.slice(st, this.p)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '').replace(/^\+/, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    return fail(`invalid value ${w}`)
  }

  array(base) {
    this.p++
    const arr = { t: 'array', items: [], tables: false }
    for (;;) {
      if (this.atEnd()) fail('unterminated array')
      if (this.peek() === ']') { this.p++; return arr }
      arr.items.push(this.value(base))
      if (this.atEnd()) fail('unterminated array')
      const c = this.peek()
      if (c === ',') { this.p++; continue }
      if (c === ']') { this.p++; return arr }
      fail('unterminated array')
    }
  }

  inline(base) {
    this.p++
    const tbl = newTable()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.peek() === '}') { this.p++; return tbl }
    for (;;) {
      if (this.atEnd()) fail('unterminated inline table')
      const segs = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.p++
      const v = this.value([...base, ...segs])
      assign(tbl, base, segs, v)
      if (this.atEnd()) fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') { this.p++; continue }
      if (c === '}') { this.p++; return tbl }
      fail('unterminated inline table')
    }
  }
}

function assign(table, base, segs, node) {
  const holder = walk(table, base, segs)
  const k = segs[segs.length - 1]
  if (holder.map.has(k)) fail(`key ${join([...base, ...segs])} is defined twice`)
  holder.map.set(k, node)
}

export function parse(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const r = doLine(lines[n], root, cur, curPath)
      if (r) { cur = r.cur; curPath = r.path }
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${n + 1}: ${e.message}`
      throw e
    }
  }
  return root
}

function doLine(s, root, cur, curPath) {
  const L = new Line(s)
  L.ws()
  const c = L.peek()
  if (c === undefined || c === '#' || c === ';') return null
  if (c === '[') return header(L, root)
  const segs = L.dotted()
  L.ws()
  if (L.peek() !== '=') fail('expected key = value')
  L.p++
  const v = L.value([...curPath, ...segs])
  if (!L.atEnd()) fail('trailing text after a value')
  assign(cur, curPath, segs, v)
  return null
}

function header(L, root) {
  L.p++
  const isArr = L.peek() === '['
  if (isArr) L.p++
  const segs = L.dotted()
  L.ws()
  if (L.peek() !== ']') fail('unterminated table header')
  L.p++
  if (isArr) {
    if (L.peek() !== ']') fail('unterminated table header')
    L.p++
  }
  if (!L.atEnd()) fail('trailing text after a table header')
  const holder = walk(root, [], segs)
  const k = segs[segs.length - 1]
  const path = join(segs)
  const ex = holder.map.get(k)
  if (isArr) {
    let arr = ex
    if (ex === undefined) {
      arr = { t: 'array', items: [], tables: true }
      holder.map.set(k, arr)
    } else if (ex.t !== 'array' || !ex.tables) fail(`${path} is not an array of tables`)
    const t = newTable()
    t.hdr = true
    arr.items.push(t)
    return { cur: t, path: segs }
  }
  if (ex === undefined) {
    const t = newTable()
    t.hdr = true
    holder.map.set(k, t)
    return { cur: t, path: segs }
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.hdr) fail(`table ${path} is defined twice`)
  ex.hdr = true
  return { cur: ex, path: segs }
}
"}

